    \n\n 3. Arduino Light Detector Flower
    \n Components Needed: \n- Arduino UNO R3 *1 \n- Breadboard *1 \n- Servo Motor *1
    \n- Jumper Wire *7 \n- 5V Power Source (Powerbank, laptop port or battery)
    \n\n Software Needed: \n Arduino IDE, Proteus (Schematic Diagram), Fritzing / Virtual Breadboard (Wiring Diagram)
    \n\n Coding (Arduino IDE): \n
    1

    #include <Servo.h>
    \n
    \n int sensorPin = A0;
    \n int servoPin  = 9;
    \n
    \n int sensorValue = 0;
    \n int servoGrad = 90;
    \n int tolerance = 40;
    \n
    \n Servo myservo;
    \n
    \n void setup() {
    \n   pinMode( sensorPin, INPUT);
    \n   myservo.attach( servoPin );
    \n   myservo.write( servoGrad );
    \n }
    \n
    \n void loop() {
    \n   sensorValue = analogRead(sensorPin);
    \n   if ( sensorValue < (512-tolerance) )
    \n   {
    \n   if (servoGrad < 180) servoGrad++;
    \n   }
    \n
    \n  if ( sensorValue > (512+tolerance) )
    \n  {
    \n    if (servoGrad > 0) servoGrad--;
    \n  }
    \n
    \n  myservo.write( servoGrad );
    \n
    \n  delay(100);
    \n }
    \n

