    #include <CapacitiveSensor.h>

// 10M resistor between send pin 4 and receive pins
CapacitiveSensor cs_4_2 = CapacitiveSensor(4,2); 
CapacitiveSensor cs_4_6 = CapacitiveSensor(4,6); 
CapacitiveSensor cs_4_8 = CapacitiveSensor(4,8); 

int buzzerPin = 10;

void setup() {
   Serial.begin(9600);
}

void loop() {
    long total1 = cs_4_2.capacitiveSensor(30);
    long total2 = cs_4_6.capacitiveSensor(30);
    long total3 = cs_4_8.capacitiveSensor(30);

    if (total1 > 1000) tone(buzzerPin, 261); // C4
    else if (total2 > 1000) tone(buzzerPin, 293); // D4
    else if (total3 > 1000) tone(buzzerPin, 329); // E4
    else noTone(buzzerPin);

    delay(10);
}
    int sensorPin = A0; // Water level sensor
int ledPin = 13;    // Indicator LED

void setup() {
  pinMode(ledPin, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int level = analogRead(sensorPin);
  Serial.print("Water Level: ");
  Serial.println(level);

  if (level > 300) { 
    digitalWrite(ledPin, HIGH);
  } else {
    digitalWrite(ledPin, LOW);
  }
  delay(500);
}
    #include <LiquidCrystal.h>

// Initialize LCD (RS, E, D4, D5, D6, D7)
LiquidCrystal lcd(12, 11, 5, 4, 3, 2);
int timeRemaining = 60; // 60 seconds

void setup() {
  lcd.begin(16, 2);
  lcd.print("Countdown Timer:");
}

void loop() {
  if (timeRemaining > 0) {
    lcd.setCursor(0, 1);
    lcd.print(timeRemaining);
    lcd.print(" Secs remaining ");
    delay(1000);
    timeRemaining--;
  } else {
    lcd.setCursor(0, 1);
    lcd.print("Time's UP!      ");
  }
}
    int controlPin = 9; // Base of the NPN transistor

void setup() {
  pinMode(controlPin, OUTPUT);
}

void loop() {
  // Turn on external load (e.g., LED strip or Motor)
  digitalWrite(controlPin, HIGH);
  delay(1000);

  // Turn off external load
  digitalWrite(controlPin, LOW);
  delay(1000);
}
    #include "SevSeg.h"
SevSeg sevseg;

void setup() {
  byte numDigits = 4;
  byte digitPins[] = {2, 3, 4, 5};
  byte segmentPins[] = {6, 7, 8, 9, 10, 11, 12, 13};
  bool resistorsOnSegments = true;

  sevseg.begin(COMMON_CATHODE, numDigits, digitPins, segmentPins, resistorsOnSegments);
  sevseg.setBrightness(90);
}

void loop() {
  sevseg.setNumber(1234, 1); // Display 123.4
  sevseg.refreshDisplay();   // Must run repeatedly
}
    #include <Servo.h>

Servo myServo;
int ldrPin = A0; // Photoresistor
int servoPin = 9;

void setup() {
  myServo.attach(servoPin);
  Serial.begin(9600);
}

void loop() {
  int lightVal = analogRead(ldrPin);
  // Map light reading (0-1023) to Servo angle (0-180)
  int angle = map(lightVal, 0, 1023, 0, 180);

  myServo.write(angle);

  delay(15);
}
    // Basic GSR (Galvanic Skin Response) / Polygraph
int gsrPin = A0;

void setup() {
  // Open serial at 9600 to view in Arduino Serial Plotter
  Serial.begin(9600);
}

void loop() {
  int gsrValue = analogRead(gsrPin);
  // Print value so Serial Plotter can graph it
  Serial.println(gsrValue);
  delay(50); // Small delay for stable plotting
}
    #include <LiquidCrystal_I2C.h>

// I2C LCD address 0x27, 16 columns, 2 rows
LiquidCrystal_I2C lcd(0x27, 16, 2);

void setup() {
  Serial.begin(9600);
  lcd.init();
  lcd.backlight();
  lcd.print("Waiting for PC...");
}

void loop() {
  // Expects data from PC script like: "CPU:45% RAM:60%"
  if (Serial.available() > 0) {
    String data = Serial.readStringUntil(10);
    lcd.clear();
    lcd.setCursor(0, 0);
    lcd.print(data.substring(0, 8)); // E.g., "CPU: 45%"
    lcd.setCursor(0, 1);
    lcd.print(data.substring(9));    // E.g., "RAM: 60%"
  }
}
    int trigPin = 9;
int echoPin = 10;

void setup() {
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
  Serial.begin(9600);
}

void loop() {
  // Send a 10us pulse to trigger
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // Measure echo duration
  long duration = pulseIn(echoPin, HIGH);

  // Calculate distance in cm (Speed of sound = 343m/s)
  int distance = duration * 0.034 / 2;

  Serial.print("Distance: ");
  Serial.print(distance);
  Serial.println(" cm");
  delay(500);
}
